records = [
    {'city': '杭州', 'product': 'A', 'amount': 120},
    {'city': '杭州', 'product': 'B', 'amount': 80},
    {'city': '上海', 'product': 'A', 'amount': 200},
    {'city': '杭州', 'product': 'A', 'amount': 60},
    {'city': '上海', 'product': 'B', 'amount': 40},
]


def group_sum(records, key, value):
    totals = {}
    for record in records or []:
        if not isinstance(record, dict):
            continue
        name = record.get(key)
        amount = record.get(value)
        if name is None or isinstance(amount, bool) or not isinstance(amount, (int, float)):
            continue
        totals[name] = totals.get(name, 0) + amount
    return totals


def group_agg(records, key, value):
    buckets = {}
    for record in records or []:
        if not isinstance(record, dict):
            continue
        name = record.get(key)
        amount = record.get(value)
        if name is None or isinstance(amount, bool) or not isinstance(amount, (int, float)):
            continue
        bucket = buckets.setdefault(name, {'sum': 0, 'count': 0, 'max': amount})
        bucket['sum'] += amount
        bucket['count'] += 1
        bucket['max'] = max(bucket['max'], amount)
    result = {}
    for name, bucket in buckets.items():
        result[name] = {
            'sum': bucket['sum'],
            'count': bucket['count'],
            'avg': round(bucket['sum'] / bucket['count'], 2),
            'max': bucket['max'],
        }
    return result


def top_groups(records, key, value, n=2):
    totals = group_sum(records, key, value)
    ranked = sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))
    return ranked[:n]


print(group_sum(records, 'city', 'amount'))
print(group_agg(records, 'city', 'amount'))
print(top_groups(records, 'city', 'amount', 2))
